content.text:
@media (max-width: 1040px) {
  .party-layout { grid-template-columns: 1fr; }
  .party-side { display: grid; grid-template-columns: 1fr 1fr; align-items: start; }
  .party-side .panel-soft { grid-column: 1 / -1; }
  .detail-screen { grid-template-columns: 250px minmax(0,1fr); }
  .map-screen { grid-template-columns: 1fr; }
  .map-side { display: grid; grid-template-columns: 1fr 1fr; }
  .map-side .map-help { grid-column: 1 / -1; }
  .title-content { grid-template-columns: 1fr; justify-items: center; text-align: center; gap: 10px; padding-bottom: 70px; }
  .title-left { align-items: center; }
  .title-tagline { text-align: center; }
  .title-actions { justify-content: center; }
  .title-right { min-height: 280px; width: min(560px, 100%); }
  .title-mon img { width: 116px; height: 116px; }
}

@media (max-width: 760px) {
  .hud-nav .nav-label, .hud-nav .nav-key { display: none; }
  .hud-nav .nav-btn { min-width: 38px; padding: 6px; }
  .hud-nav .nav-icon { font-size: 17px; }
  .hud-trainer { padding: 5px 9px 5px 5px; }
  .trainer-avatar { width: 34px; height: 34px; }
  .trainer-copy { gap: 0; }
  .trainer-line strong { font-size: 11.5px; }
  .trainer-title-line { font-size: 7px; }
  .trainer-sub { display: none; }
  .hud-center { display: none; }
  .hud-quest { min-width: 134px; max-width: 190px; padding: 6px 9px; }
  .hud-quest strong { font-size: 10px; }
  .quest-obj { font-size: 8px; }
  .hud-lead { display: none; }
  .party-dock {
    position: absolute;
    top: calc(58px + env(safe-area-inset-top));
    left: 50%;
    transform: translateX(-50%);
    margin: 0;
    padding: 4px 6px;
    background: linear-gradient(180deg, rgba(17,27,28,0.82), rgba(10,16,17,0.78));
  }
  .hud-hint { display: none; }
  .hud-bottom { margin-bottom: 58px; align-items: flex-start; }
  #toast-layer { top: calc(120px + env(safe-area-inset-top)); }
  .dock-slot { width: 40px; height: 48px; padding: 2px 3px 2px; }
  .dock-sprite { width: 27px; height: 27px; }
  .dock-lv { font-size: 6.5px; }
  .mobile-controls { display: block; }

  .screen-head { padding: 15px 15px 12px; }
  .screen-body { padding: 15px; }
  .screen-foot { padding: 10px 15px; }
  .screen-head h2 { font-size: 20px; }

  .party-grid { grid-template-columns: 1fr; }
  .party-side { grid-template-columns: 1fr; }
  .party-card { grid-template-columns: 68px minmax(0,1fr); }
  .party-portrait { width: 68px; height: 68px; }
  .party-actions { justify-content: flex-start; }

  .detail-screen { grid-template-columns: 1fr; }
  .detail-art { position: static; }
  .detail-sprite-wrap { min-height: 170px; }
  .detail-sprite-wrap .pixel-sprite { max-width: 150px; max-height: 150px; }
  .detail-meta-grid { grid-template-columns: 1fr; }

  .dex-filters { grid-template-columns: 1fr 1fr; }
  .dex-filters .search { grid-column: 1 / -1; }
  .dex-entry { grid-template-columns: 1fr; }
  .dex-entry-art { flex-direction: row; flex-wrap: wrap; justify-content: center; }
  .dex-entry-art .pixel-sprite { max-width: 120px; max-height: 120px; }
  .dex-desc { flex: 1 1 220px; text-align: left; }
  .dex-meta { flex: 1 1 100%; }

  .map-side { grid-template-columns: 1fr; }
  .help-grid { grid-template-columns: 1fr; }
  .menu-actions { grid-template-columns: 1fr; }
  .breed-grid { grid-template-columns: 1fr; }
  .starter-grid { grid-template-columns: 1fr; }
  .starter-card { flex-direction: row; text-align: left; align-items: center; }
  .starter-card .starter-art { min-height: 64px; }
  .starter-card .starter-art img { width: 62px; height: 62px; }

  .battle-top { padding: 8px 10px; }
  .battle-kind { font-size: 7.5px; }
  .battle-stage { min-height: 220px; }
  .battle-card { width: min(240px, 47vw); padding: 7px 8px; }
  .battle-card.enemy-card { left: 8px; top: 8px; }
  .battle-card.player-card { right: 8px; bottom: 8px; }
  .battle-name-row strong { font-size: 11.5px; }
  .battle-hp-text { font-size: 7px; }
  .battle-meta .element-badge { font-size: 8px; padding: 1px 5px 1px 3px; }
  .battle-meta .element-badge .el-glyph { width: 12px; height: 12px; font-size: 8px; }
  .battle-meta .rarity-badge { display: none; }
  .combatant.enemy-combatant { right: 6%; top: 16%; }
  .combatant.player-combatant { left: 5%; bottom: 17%; }
  .combatant img { width: clamp(96px, 25vw, 150px); height: clamp(96px, 25vw, 150px); }
  .battle-platform { width: 130px; height: 38px; }
  .battle-console { grid-template-columns: 1fr; gap: 4px; padding: 8px 10px 5px; }
  .battle-log { display: none; }
  .battle-message { font-size: 11.5px; min-height: 30px; }
  .battle-actions { padding: 6px 10px 10px; }
  .battle-toolbar .btn { font-size: 10px; min-height: 30px; padding: 4px 6px; }
  .battle-move-grid { grid-template-columns: 1fr 1fr; gap: 4px; }
  .move-btn { grid-template-columns: 22px minmax(0,1fr) auto; padding: 5px 6px; }
  .move-btn strong { font-size: 10px; }
  .move-btn .move-icon { width: 22px; height: 22px; flex-basis: 22px; font-size: 10px; }
  .battle-list { grid-template-columns: 1fr; }
  .battle-subpanel { max-height: 140px; }
  .battle-result { padding: 12px 10px 18px; }
  .title-footer { font-size: 8px; }
  .title-footer span:last-child { display: none; }
}

@media (max-width: 420px) {
  .battle-card { width: 46vw; }
  .battle-card .battle-name-row strong { font-size: 10.5px; }
  .battle-card .battle-lv { font-size: 7.5px; }
  .hud-quest { display: none; }
  .party-dock .dock-slot:nth-child(n+5) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; scroll-behavior: auto !important; }
}

