    const a=window.__AETHERIA__; const wait=ms=>new Promise(r=>setTimeout(r,ms));
    const out=[];
    a.startWildBattle(a.world.wilds[0]); await wait(2600);
    out.push(['battleOpen', !!document.querySelector('.battle-overlay')]);
    const btn = t => [...document.querySelectorAll('.battle-overlay button')].find(b=>b.textContent.includes(t));
    btn('Bag')?.click(); await wait(200); out.push(['bagPanel', !!document.querySelector('.battle-subpanel')]);
    btn('Catch')?.click(); await wait(200); out.push(['catchPanel', document.querySelector('.battle-list-row')?.textContent.includes('chance')]);
    btn('Party')?.click(); await wait(200); out.push(['partyPanel', !!document.querySelector('.battle-list-row')]);
    btn('Fight')?.click(); await wait(200);
    const hp0 = a.battleUI.battle.enemy.hp;
    document.querySelector('.move-btn')?.click(); await wait(3200);
    const hp1 = a.battleUI?.battle.enemy.hp;
    out.push(['turnAdvanced', hp0 !== hp1, hp0, hp1, a.battleUI?.busy, a.battleUI?.battle?.turn]);
    return out;

